// Generated by ai-hq earnings_notes/publish.py. One shared team login via HTTP Basic Auth.
export const config = { matcher: ["/((?!favicon.ico).*)"] };

export default function middleware(req) {
  const user = process.env.DESK_USER || "";
  const pass = process.env.DESK_PASSWORD || "";
  if (!user || !pass) {
    return new Response("Earnings notes: DESK_USER and DESK_PASSWORD are not set in Vercel.", { status: 503 });
  }
  const want = "Basic " + btoa(user + ":" + pass);
  const got = req.headers.get("authorization") || "";
  if (got.length === want.length && safeEqual(got, want)) return;   // continue to the static file
  return new Response("Earnings notes: sign in", {
    status: 401,
    headers: { "WWW-Authenticate": 'Basic realm="Earnings notes", charset="UTF-8"', "Cache-Control": "no-store" },
  });
}

function safeEqual(a, b) {
  let r = 0;
  for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return r === 0;
}
